func (this *Indodax) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	//
	// {
	//     "tickers": {
	//         "btc_idr": {
	//             "high": "120009000",
	//             "low": "116735000",
	//             "vol_btc": "218.13777777",
	//             "vol_idr": "25800033297",
	//             "last": "117088000",
	//             "buy": "117002000",
	//             "sell": "117078000",
	//             "server_time": 1571207881
	//         }
	//     }
	// }
	//

	r1 := <-this.PublicGetApiTickerAll(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var tickers map[string]any = SafeMapTyped(response, "tickers")
	var keys []string = nil
	if tickers != nil {
		keys = make([]string, 0, len(tickers))
		for objectKey := range tickers {
			keys = append(keys, objectKey)
		}
	}
	var parsedTickers map[string]any = map[string]any{}
	for i := 0; i < len(keys); i++ {
		var key string = keys[i]
		var rawTicker any = tickers[key]
		var marketId string = strings.Replace(key, "_", "", 1)
		var market map[string]any = this.SafeMarket(marketId)
		var parsed map[string]any = TickerToMap(this.ParseTicker(rawTicker, market))
		parsedTickers[marketId] = parsed
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.FilterByArrayTickers(parsedTickers, "symbol", symbols))}
	return nil
}
