/**
 * @method
 * @name indodax#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Indodax) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Indodax) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var selectedTimeframe *string = this.SafeString(this.Timeframes, timeframe, timeframe)
	var now int64 = this.Seconds()
	var until *int64 = this.SafeInteger(params, "until", now)
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"until"})
	var request map[string]any = map[string]any{
		"to":     until,
		"tf":     selectedTimeframe,
		"symbol": market["id"],
	}
	var limitResolved int64 = func() int64 {
		if limit == nil {
			return 1000
		}
		return *limit
	}()
	if since != nil {
		request["from"] = math.Floor(float64(*since) / 1000)
	} else {
		var duration int64 = this.ParseTimeframe(timeframe)
		if limit == nil {
			request["from"] = now - (1000 * duration) - 1
		} else {
			request["from"] = now - (*limit * duration) - 1
		}
	}

	listEp929 := <-this.PublicGetTradingviewHistoryV2(this.Extend(request, paramsOmitted))
	if listEp929.Err != nil {
		panic(listEp929.Err)
	}
	var response []any = listEp929.Value

	//
	//     [
	//         {
	//             "Time": 1708416900,
	//             "Open": 51707.52,
	//             "High": 51707.52,
	//             "Low": 51707.52,
	//             "Close": 51707.52,
	//             "Volume": "0"
	//         }
	//     ]
	//
	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(this.ToArray(response), market, timeframe, since, limitResolved))}
	return nil
}
func (this *Indodax) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"open":      "open",
		"filled":    "closed",
		"cancelled": "canceled",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Indodax) ParseOrder(order any, optionalArgs ...any) Order {
	//
	//     {
	//         "order_id": "12345",
	//         "submit_time": "1392228122",
	//         "price": "8000000",
	//         "type": "sell",
	//         "order_ltc": "100000000",
	//         "remain_ltc": "100000000"
	//     }
	//
	// market closed orders - note that the price is very high
	// and does not reflect actual price the order executed at
	//
	//     {
	//       "order_id": "49326856",
	//       "type": "sell",
	//       "price": "1000000000",
	//       "submit_time": "1618314671",
	//       "finish_time": "1618314671",
	//       "status": "filled",
	//       "order_xrp": "30.45000000",
	//       "remain_xrp": "0.00000000"
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "order_id": 666883,
	//        "client_order_id": "clientx-sj82ks82j",
	//        "type": "sell",
	//        "pair": "btc_idr",
	//        "balance": {
	//            "idr": "33605800",
	//            "btc": "0.00000000",
	//            ...
	//            "frozen_idr": "0",
	//            "frozen_btc": "0.00000000",
	//            ...
	//        }
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var side *string = this.SafeString(order, "type")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status", "open"))
	var symbol any = nil
	var cost *string = nil
	var price *string = this.SafeString(order, "price")
	var amount *string = nil
	var remaining *string = nil
	var filled *string = nil
	var marketId *string = this.SafeString(order, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	if marketResolved != nil {
		symbol = marketResolved["symbol"]
		var quoteId string = *this.SafeString(marketResolved, "quoteId", "")
		var baseId string = *this.SafeString(marketResolved, "baseId", "")
		if (marketResolved["quoteId"] == "idr") && (this.SafeString(order, "order_rp") != nil) {
			quoteId = "rp"
		}
		if (marketResolved["baseId"] == "idr") && (this.SafeString(order, "remain_rp") != nil) {
			baseId = "rp"
		}
		cost = this.SafeString(order, "order_"+quoteId)
		amount = this.SafeString(order, "order_"+baseId)
		remaining = this.SafeString(order, "remain_"+baseId)
		// filled buy orders on idr-quoted markets carry the executed base amount
		// only in a dynamic receive_{base} field, https://github.com/ccxt/ccxt/issues/26413
		filled = this.SafeString(order, "receive_"+baseId)
	}
	var timestamp *int64 = this.SafeInteger(order, "submit_time")
	var fee any = nil
	var id *string = this.SafeString(order, "order_id")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      this.SafeString(order, "client_order_id"),
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               "limit",
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               cost,
		"average":            nil,
		"amount":             amount,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             nil,
	})
}

/**
 * @method
 * @name indodax#fetchOrder
 * @description fetches information on an order made by the user
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#get-order-endpoints
 * @param {string} id order id
 * @param {string} symbol unified symbol of the market the order was made in
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) FetchOrderAsync(id string, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.fetchOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Indodax) fetchOrderBody(ch chan AsyncResult[Order], id string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchOrder() requires a symbol argument"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":     market["id"],
		"order_id": id,
	}

	r1 := <-this.PrivatePostGetOrder(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	var orders map[string]any = SafeMapTyped(response, "return")
	var order map[string]any = OrderToMap(this.ParseOrder(this.Extend(map[string]any{
		"id": id,
	}, orders["order"]), market))
	order["info"] = response

	ch <- AsyncResult[Order]{Value: OrderFromMap(order)}
	return nil
}

/**
 * @method
 * @name indodax#fetchOpenOrders
 * @description fetch all unfilled currently open orders
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#open-orders-endpoints
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch open orders for
 * @param {int} [limit] the maximum number of  open orders structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) FetchOpenOrdersAsync(optionalArgs ...any) <-chan AsyncResult[[]Order] {
	ch := make(chan AsyncResult[[]Order], 1)
	go this.fetchOpenOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Indodax) fetchOpenOrdersBody(ch chan AsyncResult[[]Order], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = nil
	var request map[string]any = map[string]any{}
	if symbol != nil {
		market = this.Market(symbol)
		request["pair"] = market["id"]
	}

	r1 := <-this.PrivatePostOpenOrders(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var openOrdersResult map[string]any = SafeMapTyped(response, "return")
	var rawOrders any = openOrdersResult["orders"]
	// { success: 1, return: { orders: null }} if no orders
	if IsEqual(rawOrders, nil) {

		ch <- AsyncResult[[]Order]{Value: OrdersFromList([]any{})}
		return nil
	}
	// { success: 1, return: { orders: [ ... objects ] }} for orders fetched by symbol
	if symbol != nil {

		ch <- AsyncResult[[]Order]{Value: OrdersFromList(this.ParseOrders(rawOrders, market, since, limit))}
		return nil
	}
	// { success: 1, return: { orders: { marketid: [ ... objects ] }}} if all orders are fetched
	var ordersDict map[string]any = SafeMapTyped(openOrdersResult, "orders")
	var marketIds []string = nil
	if ordersDict != nil {
		marketIds = make([]string, 0, len(ordersDict))
		for objectKey := range ordersDict {
			marketIds = append(marketIds, objectKey)
		}
	}
	var exchangeOrders []any = []any{}
	for i := 0; i < len(marketIds); i++ {
		var marketId string = marketIds[i]
		var marketOrders any = ordersDict[marketId]
		market = this.SafeMarket(marketId)
		var parsedOrders []any = this.ParseOrders(marketOrders, market, since, limit)
		exchangeOrders = this.ArrayConcat(exchangeOrders, parsedOrders)
	}

	ch <- AsyncResult[[]Order]{Value: OrdersFromList(exchangeOrders)}
	return nil
}

