	r1 := <-this.PrivatePostCancelOrder(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//    {
	//        "success": 1,
	//        "return": {
