func (this *Indodax) fetchDepositAddressesBody(ch chan AsyncResult[[]DepositAddress], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.PrivatePostGetInfo(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//    {
	//        success: '1',
	//        return: {
	//            server_time: '1708031570',
	//            balance: {
	//                idr: '29952',
	//                ...
	//            },
	//            balance_hold: {
	//                idr: '0',
	//                ...
	//            },
	//            address: {
	//                btc: '1KMntgzvU7iTSgMBWc11nVuJjAyfW3qJyk',
	//                ...
	//            },
	//            memo_is_required: {
	//                btc: { mainnet: false },
	//                ...
	//            },
	//            network: {
	//                btc: 'mainnet',
	//                ...
	//            },
	//            user_id: '276011',
	//            name: '',
	//            email: 'testbitcoincoid@mailforspam.com',
	//            profile_picture: null,
	//            verification_status: 'unverified',
	//            gauth_enable: true,
	//            withdraw_status: '0'
	//        }
	//    }
	//
	var data map[string]any = SafeMapTyped(response, "return")
	var addresses map[string]any = SafeMapTyped(data, "address")
	var networks map[string]any = SafeMapTyped(data, "network")
	var addressKeys []string = nil
	if addresses != nil {
		addressKeys = make([]string, 0, len(addresses))
		for objectKey := range addresses {
			addressKeys = append(addressKeys, objectKey)
		}
	}
	var result []any = []any{}
	for i := 0; i < len(addressKeys); i++ {
		var marketId string = addressKeys[i]
		var code *string = this.SafeCurrencyCode(marketId)
		var address *string = this.SafeString(addresses, marketId)
		if (address != nil) && ((codes == nil) || (this.InArray(code, codes))) {
			this.CheckAddress(address)
			var network any = nil
			if _, ok := networks[marketId]; ok {
				var networkId *string = this.SafeString(networks, marketId)
				if networkId == nil {
					panic(ExchangeError(this.Id + " fetchDepositAddresses() missing networkId"))
				}
				if strings.Index(*networkId, ",") >= 0 {
					network = []any{}
					if networkId == nil {
						panic(ExchangeError(this.Id + " fetchDepositAddresses() missing networkId"))
					}
					var networkIds []string = strings.Split(*networkId, ",")
					for j := 0; j < len(networkIds); j++ {
						var _netIdTmp *string = this.NetworkIdToCode(networkIds[j], code)
						if _netIdTmp != nil {
							AppendToArray(&network, strings.ToUpper(*_netIdTmp))
						}
					}
				} else {
					var _netIdTmp *string = this.NetworkIdToCode(networkId, code)
					if _netIdTmp != nil {
						network = strings.ToUpper(*_netIdTmp)
					}
				}
			}
			var finalNetwork any = network // java req
			if code != nil {
				result = append(result, map[string]any{
					"info":     map[string]any{},
					"currency": code,
					"network":  finalNetwork,
					"address":  address,
					"tag":      nil,
				})
			}
		}
	}

	ch <- AsyncResult[[]DepositAddress]{Value: DepositAddressesFromList(this.ToArray(result))}
	return nil
}
func (this *Indodax) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var apiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url *string = apiUrl
	var privateBody any = nil
	var privateHeaders any = nil
	var isPublic bool = (apiName == "public")
	if isPublic {
		var query any = this.Omit(params, this.ExtractParams(path))
		var requestPath string = "/" + this.ImplodeParams(path, params)
		url = SafeStringPtr(*apiUrl + requestPath)
		if queryMap, _ := query.(map[string]any); len(queryMap) > 0 {
			url = SafeStringPtr(*apiUrl + requestPath + "?" + this.UrlencodeWithArrayRepeat(query))
		}
	} else {
		this.CheckRequiredCredentials()
		privateBody = this.Urlencode(this.Extend(map[string]any{
			"method":     path,
			"timestamp":  this.Nonce(),
			"recvWindow": this.Options["recvWindow"],
		}, params))
		privateHeaders = map[string]any{
			"Content-Type": "application/x-www-form-urlencoded",
			"Key":          this.ApiKey,
			"Sign":         this.Hmac(this.Encode(privateBody), this.Encode(this.Secret), sha512),
		}
	}
	var requestBody any = privateBody
	if isPublic {
		requestBody = nil
	}
	var requestHeaders any = privateHeaders
	if isPublic {
		requestHeaders = nil
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": requestHeaders,
	}
}
func (this *Indodax) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil
	}
	// { success: 0, error: "invalid order." }
	// or
	// [{ data, ... }, { ... }, ... ]
	// {"success":"1","status":"approved","withdraw_currency":"strm","withdraw_address":"0x2b9A8cd5535D99b419aEfFBF1ae8D90a7eBdb24E","withdraw_amount":"2165.05767839","fee":"21.11000000","amount_after_fee":"2143.94767839","submit_time":"1730759489","withdraw_id":"strm-3423","txid":""}
	if IsArray(response) {
		return nil // public endpoints may return []-arrays
	}
	var error *string = this.SafeString(response, "error", "")
	var status *string = this.SafeString(response, "success")
	if (status == nil) && (error != nil && *error == "") {
		return nil // no 'success' property on public responses
	}
	if status != nil && *status == "approved" {
		return nil
	}
	if *this.SafeInteger(response, "success", 0) == 1 {
		// { success: 1, return: { orders: [] }}
		if !(InOp(response, "return")) {
			panic(ExchangeError(this.Id + ": malformed response: " + this.Json(response)))
		} else {
			return nil
		}
	}
	var feedback string = this.Id + " " + body
	this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
	this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
	panic(ExchangeError(feedback))
}

func NewIndodax(userConfig map[string]any) *Indodax {
	p := newIndodax()
	p.Init(userConfig)
	return p
}

func (this *Indodax) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

